        console.warn(`${MODULE_ID} | Could not create ${directory}`, error);
      }
    }
  }

  const blob = await fetchGhostShipMapBlob();
  const file = new File([blob], MAP_FILENAME, { type: blob.type || "image/webp" });
  const directory = directories.at(-1);
